using System.ComponentModel.DataAnnotations;

public class ProductInputModel
{
    public int Id { get; set; }

    [Required(ErrorMessage = "Product name is required.")]
    [StringLength(100, ErrorMessage = "Name cannot exceed 100 characters.")]
    public string Name { get; set; }

    [Required]
    [Range(0.01, 9999.99, ErrorMessage = "Price must be between 0.01 and 9999.99.")]
    public decimal Price { get; set; }

    [Url(ErrorMessage = "Please enter a valid image URL.")]
    public string ImageUrl { get; set; }

    [Compare(nameof(ImageUrl), ErrorMessage = "Image URLs do not match.")]
    public string ConfirmImageUrl { get; set; }
}

// Controller action
[HttpPost]
public IActionResult Create(ProductInputModel model)
{
    if (!ModelState.IsValid)
    {
        // ModelState contains all validation errors
        return View(model);
    }

    _productRepo.Add(model);
    return RedirectToAction("Index");
}
